package io.github.diodeme.ji.acp.v2.preview;

import java.util.List;
import java.util.Map;
import java.util.Objects;
import java.util.Optional;

/** Isolated draft ACP v2 wire model. No preview type is exposed by Agent Core. */
public final class AcpV2PreviewModel {
    public static final int PROTOCOL_VERSION = 2;

    private AcpV2PreviewModel() { }

    public sealed interface ReplayFrom permits ReplayFrom.Start {
        record Start() implements ReplayFrom { }
    }

    public sealed interface StateUpdate permits StateUpdate.Running, StateUpdate.Idle, StateUpdate.RequiresAction {
        record Running() implements StateUpdate { }
        record Idle(Optional<String> stopReason) implements StateUpdate {
            public Idle { stopReason = stopReason == null ? Optional.empty() : stopReason; }
        }
        record RequiresAction() implements StateUpdate { }
    }

    public record StructuredDiff(List<Change> changes, Optional<Patch> patch) {
        public StructuredDiff {
            changes = List.copyOf(changes);
            patch = patch == null ? Optional.empty() : patch;
            if (changes.isEmpty()) throw new IllegalArgumentException("structured diff must contain a change");
        }
    }

    public record Change(Operation operation, String oldPath, String path, String fileType, String mimeType) {
        public Change {
            Objects.requireNonNull(operation, "operation");
            path = normalize(path);
            oldPath = oldPath == null ? null : normalize(oldPath);
            if ((operation == Operation.MOVE || operation == Operation.COPY) && oldPath == null) {
                throw new IllegalArgumentException("move/copy requires oldPath");
            }
            if (operation != Operation.MOVE && operation != Operation.COPY && oldPath != null) {
                throw new IllegalArgumentException("oldPath is only valid for move/copy");
            }
        }
    }

    public record Patch(String format, String text) {
        public Patch {
            if (format == null || format.isBlank() || text == null) {
                throw new IllegalArgumentException("patch format and text are required");
            }
        }
    }

    public enum Operation { ADD, DELETE, MODIFY, MOVE, COPY }

    public record DomainProjection(
            String sessionId,
            long revision,
            List<Message> messages,
            String runId,
            StateUpdate state,
            Map<String, StructuredDiff> toolDiffs) {
        public DomainProjection {
            if (sessionId == null || sessionId.isBlank() || revision < 0) {
                throw new IllegalArgumentException("domain projection identity is invalid");
            }
            messages = List.copyOf(messages);
            toolDiffs = Map.copyOf(toolDiffs);
        }
    }

    public record Message(String id, Role role, String text) {
        public Message {
            if (id == null || id.isBlank() || role == null || text == null) {
                throw new IllegalArgumentException("message is invalid");
            }
        }
    }

    public enum Role { USER, AGENT }

    private static String normalize(String path) {
        if (path == null || path.isBlank()) throw new IllegalArgumentException("path must not be blank");
        return path.replace('\\', '/');
    }
}
